from hran_radio.exceptions import ConnectionError
from taf.transport.ssh import ssh
from collections import namedtuple
from robot.api import logger
from abc import abstractmethod, ABCMeta
import re
import six


@six.add_metaclass(ABCMeta)
class BaseConnection(object):
    def __init__(self, radio_ip, sm_ip, msm_ip):
        """
        Base class to send command form system module.

        :param radio_ip: radio module ip
        :param sm_ip: ip system module connected to radio
        :param msm_ip: master system module ip. If msm_ip != sm_ip connection
        is setup via msm to sm.
        """
        super(BaseConnection, self).__init__()
        self._radio_ip = radio_ip
        self._sm_ip = sm_ip
        self._msm_ip = msm_ip
        self.attach_error = re.compile(
            r"lxc[-_]attach: \d{1,} [Ff]ailed to get (the ){0,1}init pid|attach\.c:"
        )
        self.key_error = re.compile(r"Host key verification failed")

    @abstractmethod
    def execute_commands(self, cmd, rel):
        """
        Execute command

        :param cmd: command str
        :param rel: FSMF or ASIA str
        :return: Command output
        :rtype: str
        """

    @abstractmethod
    def wrap_command_for_rel3(self, cmd):
        """
        Return full command prepare to execute from smod rel3 on rmod

        :param cmd: command str
        :return: full command
        :rtype: str
        """

    @abstractmethod
    def wrap_command_for_rel4(self, cmd, num):
        """
        Return full command prepare to execute from smod rel4 on rmod

        :param cmd: command str
        :param num: 1 or 2 as a str. (Left, right side smod)
        :return: full command
        :rtype: str
        """

    def get_smod_release(self):
        """
        Return system module release name e.g.: FSMF or ASIA

        :return: smod release name
        :rtype: str
        """
        output = self._check_smod_release()
        if re.search(r"FSMF", output):
            return "FSMF"
        return "ASIA"

    def _check_smod_release(self):
        ssh_rel = self._set_ssh_connection()
        release = ssh_rel.run_command(
            "cat /proc/device-tree/module-identity/unit-id"
        ).stdout
        return six.ensure_str(release)

    def run_command_from_rel3(self, command):
        """
        Execute command on smod release3

        :param command: command str
        :return: command output
        :rtype: str
        """
        output = self._execute_command_rel3(command)
        if output.return_code != 0:
            raise ConnectionError
        return six.ensure_str(output.stdout)

    def run_command_from_rel4(self, command):
        """
        Execute command on smod release4

        :param command: command str
        :return: command output
        :rtype: str
        """
        output, num = self._try_on_both_side(command)
        if output.return_code != 0:
            raise ConnectionError
        return six.ensure_str(output.stdout, encoding="latin")

    def _try_on_both_side(self, command):
        for num in ["1", "2"]:
            output = self._execute_command_rel4(command, num)
            if not self.attach_error.search(
                    six.ensure_str(output.stdout, encoding="latin")
            ):
                return output, num

    def _execute_command_rel3(self, command):
        wrapped_command = self.wrap_command_for_rel3(command)
        connection = self._set_ssh_connection()
        return connection.run_command(wrapped_command)

    def _execute_command_rel4(self, command, num):
        wrapped_command = self.wrap_command_for_rel4(command, num)
        connection = self._set_ssh_connection()
        return connection.run_command(wrapped_command)

    def _set_ssh_connection(self):
        connection = ConnectionSSH(self._sm_ip, self._msm_ip)
        if self._sm_ip == self._msm_ip or self._sm_ip == "192.168.255.129":
            connection.connect()
        else:
            connection.connect_to_via_proxy()
        return connection


class ConnectionSSH(ssh):
    def __init__(self, sm_ip, msm_ip=None):
        super(ConnectionSSH, self).__init__()
        self.stdout = None
        self.return_code = None
        self._ip = sm_ip
        self._proxy_ip = msm_ip
        self._username = 'toor4nsn'
        self._password = 'oZPS0POrRieRtu'

    def connect(self):
        self.connect_to(hostname=self._ip, username=self._username, password=self._password)

    def connect_to_via_proxy(self):
        proxy = self.connect_to(hostname=self._proxy_ip, username=self._username, password=self._password)
        self.connect_to(hostname=self._ip, username=self._username, password=self._password, proxy=proxy)

    def run_command(self, command):
        self.stdout = self.execute(command, timeout=20)
        self.return_code = self.get_exit_status()
        result = namedtuple('output_shh', 'stdout return_code')
        response = result(self.stdout, self.return_code)
        return response

    def put_file_on_remote(self, localpath, remotepath):
        if self._proxy_ip and self._ip:
            logger.debug('\n[hran-radio] Putting file: ip: {} proxy_ip: {}'.format(self._ip, self._proxy_ip))
            self.connect_to_via_proxy()
        elif self._ip:
            logger.debug('\n[hran-radio] Putting file: ip: {}'.format(self._ip))
            self.connect()
        else:
            raise ConnectionError
        self.upload_file(localpath, remotepath, timeout=60)
        self.disconnect()

    def remove_file(self, filename):
        self.run_command("rm {}".format(filename))
